INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3386086, 470460, 5728, '<td valign="top">Amsterdam!!!!!</td>', 'Amsterdam!!!!!', '2007-02-20 16:37:03.000000', NULL, 1),
(3386087, 470497, 73601, '<td valign="top">great capture of emotion</td>', 'great capture of emotion', '2007-02-20 16:37:06.000000', NULL, 1),
(3386107, 470834, 73601, '<td valign="top">I think there is just too much going on here, no focal point for me</td>', 'I think there is just too much going on here, no focal point for me', '2007-02-20 16:42:01.000000', NULL, 1),
(3386114, 471160, 42100, '<td valign="top">Charming photo with these three distinguished gentlemen.  Only wished you caught them at a moment of interaction to give it that little something extra.</td>', 'Charming photo with these three distinguished gentlemen.  Only wished you caught them at a moment of interaction to give it that little something extra.', '2007-02-20 16:45:02.000000', NULL, 1),
(3386126, 470725, 42100, '<td valign="top">Great b&amp;w conversion and composition.  Really like the movement of the subject through the photo, makes it much more dynamic.  Really hate the selective desat because I don''t think it adds to this photo in any way, shape or form.  High probability though that the reason just went completely over my head.</td>', 'Great b&w conversion and composition.  Really like the movement of the subject through the photo, makes it much more dynamic.  Really hate the selective desat because I don''t think it adds to this photo in any way, shape or form.  High probability though that the reason just went completely over my head.', '2007-02-20 16:51:33.000000', NULL, 1),
(3386127, 471426, 42100, '<td valign="top">Very charming photograph with awesome use of DOF.  I also like the muted color tones.  Well done!</td>', 'Very charming photograph with awesome use of DOF.  I also like the muted color tones.  Well done!', '2007-02-20 16:52:24.000000', NULL, 1),
(3386142, 470963, 42100, '<td valign="top">Very much like this composition.  Great use of DOF and quite exquisite b&amp;w conversion.  Great job!</td>', 'Very much like this composition.  Great use of DOF and quite exquisite b&w conversion.  Great job!', '2007-02-20 16:56:07.000000', NULL, 1),
(3386169, 469759, 42100, '<td valign="top">Very good technicals on this photo.  But I don''t think it would work as well without the guys.  The younger one on a payphone and the older on a cell.  You would very much expect the roles to be reversed, typically the younger generation loving cells and the older not really embracing them.  This probably sounds really stupid...but something about the ''Do not enter'' sign really adds to this.  Very nice!</td>', 'Very good technicals on this photo.  But I don''t think it would work as well without the guys.  The younger one on a payphone and the older on a cell.  You would very much expect the roles to be reversed, typically the younger generation loving cells and the older not really embracing them.  This probably sounds really stupid...but something about the ''Do not enter'' sign really adds to this.  Very nice!', '2007-02-20 17:02:47.000000', NULL, 1),
(3386177, 467724, 6888, '<td valign="top">interesting shot, may have worked well in b/w also</td>', 'interesting shot, may have worked well in b/w also', '2007-02-20 17:06:25.000000', NULL, 1),
(3386181, 470195, 6888, '<td valign="top">i definitely like the canvas effect</td>', 'i definitely like the canvas effect', '2007-02-20 17:07:01.000000', NULL, 1),
(3386183, 471516, 6888, '<td valign="top">sky a bit overblown, but a great photojournalistic look to it</td>', 'sky a bit overblown, but a great photojournalistic look to it', '2007-02-20 17:07:31.000000', NULL, 1),
(3386185, 471481, 6888, '<td valign="top">well done...very nice</td>', 'well done...very nice', '2007-02-20 17:07:55.000000', NULL, 1),
(3386186, 470663, 6888, '<td valign="top">interesting shot</td>', 'interesting shot', '2007-02-20 17:08:39.000000', NULL, 1),
(3386189, 471468, 6888, '<td valign="top">a great shot for this challenge</td>', 'a great shot for this challenge', '2007-02-20 17:09:01.000000', NULL, 1),
(3386192, 471288, 6888, '<td valign="top">a bit uninteresting for my tastes</td>', 'a bit uninteresting for my tastes', '2007-02-20 17:09:51.000000', NULL, 1),
