(3386208, 471097, 6888, '<td valign="top">nice job</td>', 'nice job', '2007-02-20 17:11:53.000000', NULL, 1),
(3386217, 470837, 6888, '<td valign="top">had to tell what your subject is....the people are more an afterthought after the street takes in all the attention</td>', 'had to tell what your subject is....the people are more an afterthought after the street takes in all the attention', '2007-02-20 17:13:33.000000', NULL, 1),
