INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3399099, 471510, 44882, '<td valign="top">Nice scene ! I love the red jacket of the little child, the old man with his walking stick. All the persons in the picture have something interesting to look at. BUT, I wish there were not those heavy shades and maybe I would have like if cropped differently, with less of the building on the top.</td>', 'Nice scene ! I love the red jacket of the little child, the old man with his walking stick. All the persons in the picture have something interesting to look at. BUT, I wish there were not those heavy shades and maybe I would have like if cropped differently, with less of the building on the top.', '2007-02-23 18:51:06.000000', NULL, 1),
