(3399577, 468825, 66597, '<td valign="top">I really like the sense of movement here.</td>', 'I really like the sense of movement here.', '2007-02-23 22:06:33.000000', NULL, 1),
(3399578, 471403, 66597, '<td valign="top">Excellent use of relative size to capture an emotion!</td>', 'Excellent use of relative size to capture an emotion!', '2007-02-23 22:06:53.000000', NULL, 1),
(3399582, 471155, 66597, '<td valign="top">This captures a sense of desolation very well. It makes me want to know her story.</td>', 'This captures a sense of desolation very well. It makes me want to know her story.', '2007-02-23 22:08:03.000000', NULL, 1),
(3399583, 471518, 66597, '<td valign="top">I like the angle on this.</td>', 'I like the angle on this.', '2007-02-23 22:08:22.000000', NULL, 1),
