(3400288, 471076, 30982, '<td valign="top">Another great example of how color can work well.  I like the desat on the sides, too - adds to the warmth of the color she''s moving into, and the light is wonderful!  Very nicely done.</td>', 'Another great example of how color can work well.  I like the desat on the sides, too - adds to the warmth of the color she''s moving into, and the light is wonderful!  Very nicely done.', '2007-02-24 07:12:21.000000', NULL, 1),
(3400289, 471403, 30982, '<td valign="top">Excellent use of grand scale to convey the mood implied by your title.</td>', 'Excellent use of grand scale to convey the mood implied by your title.', '2007-02-24 07:13:01.000000', NULL, 1),
(3400291, 470641, 30982, '<td valign="top">To me, it looks as though it was set up, but the overall effect is good.</td>', 'To me, it looks as though it was set up, but the overall effect is good.', '2007-02-24 07:16:46.000000', NULL, 1),
(3400292, 471497, 30982, '<td valign="top">Very effective - like the use of lines in this.</td>', 'Very effective - like the use of lines in this.', '2007-02-24 07:17:22.000000', NULL, 1),
