(3404641, 470979, 27133, '<td valign="top">Congrats on fourth place.  Love the tones.</td>', 'Congrats on fourth place.  Love the tones.', '2007-02-26 00:06:39.000000', NULL, 0),
(3404643, 471151, 37818, '<td valign="top">Way to go bro!!<br/>Love this...I think his brother lives here</td>', 'Way to go bro!!Love this...I think his brother lives here', '2007-02-26 00:06:50.000000', NULL, 0),
(3404644, 471237, 27133, '<td valign="top">Congrats on fifth place.  So sad.</td>', 'Congrats on fifth place.  So sad.', '2007-02-26 00:06:55.000000', NULL, 0),
